using System;
using System.Drawing;
using System.IO;
using System.Linq;
using PowerPointIntelligence.AddIn;
using Office=Microsoft.Office.Core;
using PowerPoint=Microsoft.Office.Interop.PowerPoint;
internal static class UniversalConnectorOfficeTests
{
    private static int count;
    private static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL universal connector Office: "+name);count++;Console.WriteLine("PASS universal connector Office: "+name);}
    private static PowerPoint.Shape ById(PowerPoint.Slide slide,int id){return slide.Shapes.Cast<PowerPoint.Shape>().Single(s=>s.Id==id);}
    private static ConnectorSpec Link(PowerPoint.Shape a,PowerPoint.Shape b,string route="straight"){return new ConnectorSpec {Route=route,AutoRoute=false,Begin=new ConnectorEndpoint {ShapeId=a.Id,Site=1},End=new ConnectorEndpoint {ShapeId=b.Id,Site=3},BeginArrow="open",EndArrow="stealth",Dash="dash",Weight=2.5f};}
    internal static void Run(PowerPoint.Application app,string outputDirectory)
    {
        if(app==null)throw new ArgumentNullException("app");Directory.CreateDirectory(outputDirectory);count=0;PowerPoint.Presentation owned=null;string file=Path.Combine(Path.GetFullPath(outputDirectory),"universal-connectors-native-"+Guid.NewGuid().ToString("N")+".pptx");
        Console.WriteLine("UNIVERSAL CONNECTOR Office="+app.Version+"; process="+(Environment.Is64BitProcess?"x64":"x86"));
        try
        {
            owned=app.Presentations.Add(Office.MsoTriState.msoTrue);owned.PageSetup.SlideWidth=960;owned.PageSetup.SlideHeight=540;owned.Windows[1].ViewType=PowerPoint.PpViewType.ppViewNormal;var slide=owned.Slides.Add(1,PowerPoint.PpSlideLayout.ppLayoutBlank);slide.Select();
            var a=slide.Shapes.AddShape(Office.MsoAutoShapeType.msoShapeRectangle,40,60,120,80);var b=slide.Shapes.AddShape(Office.MsoAutoShapeType.msoShapeRectangle,300,70,120,80);var c=slide.Shapes.AddShape(Office.MsoAutoShapeType.msoShapeRectangle,600,80,120,80);c.TextFrame.TextRange.Text="Unrelated target";int aid=a.Id,bid=b.Id,cid=c.Id;
            var line=UniversalConnectors.Create(app,Link(a,b));int lineId=line.Id;Check(line.Connector==Office.MsoTriState.msoTrue&&line.ConnectorFormat.BeginConnectedShape.Id==aid&&line.ConnectorFormat.EndConnectedShape.Id==bid,"native site endpoints attach to intended shapes");Check(line.Line.BeginArrowheadStyle==Office.MsoArrowheadStyle.msoArrowheadOpen&&line.Line.EndArrowheadStyle==Office.MsoArrowheadStyle.msoArrowheadStealth&&Math.Abs(line.Line.Weight-2.5f)<.01,"both arrows and native styling apply");
            // Native detach must override the old persistent target rather than reconnecting it.
            line.ConnectorFormat.BeginDisconnect();UniversalConnectors.Reflow(app);var current=UniversalConnectors.Read(line);Check(line.ConnectorFormat.BeginConnected==Office.MsoTriState.msoFalse&&current.Begin.Kind=="free"&&current.Begin.ShapeId==0,"reflow preserves native user detachment");
            line.ConnectorFormat.BeginConnect(c,2);UniversalConnectors.Reflow(app);current=UniversalConnectors.Read(line);Check(current.Begin.Kind=="site"&&current.Begin.ShapeId==cid&&current.Begin.Site==2&&line.ConnectorFormat.BeginConnectedShape.Id==cid,"reflow adopts native user reattachment");
            line.ConnectorFormat.EndDisconnect();line.ConnectorFormat.EndConnect(a,3);UniversalConnectors.Reflow(app);Check(UniversalConnectors.Read(line).End.ShapeId==aid&&line.ConnectorFormat.EndConnectedShape.Id==aid,"both endpoint reattachments supersede obsolete metadata");
            UniversalConnectors.Reflow(app);owned.SaveAs(file,PowerPoint.PpSaveAsFileType.ppSaveAsOpenXMLPresentation);Check(owned.Saved==Office.MsoTriState.msoTrue,"actual save establishes clean baseline before no-op reflow");var savedTrace=new System.Collections.Generic.List<string>();UniversalConnectors.Reflow(app,stage=>savedTrace.Add(stage+":"+owned.Saved));if(owned.Saved!=Office.MsoTriState.msoTrue)File.WriteAllLines(Path.Combine(outputDirectory,"connector-saved-state.txt"),savedTrace);Check(owned.Saved==Office.MsoTriState.msoTrue,"no-op reflow leaves Saved state unchanged; read/mutation stages recorded on failure");
            var free=UniversalConnectors.Create(app,new ConnectorSpec {Route="curve",Begin=new ConnectorEndpoint {Kind="free",X=100,Y=260},End=new ConnectorEndpoint {Kind="free",X=350,Y=310},BeginArrow="triangle",EndArrow="none"});int freeId=free.Id;Check(free.ConnectorFormat.BeginConnected==Office.MsoTriState.msoFalse&&free.ConnectorFormat.EndConnected==Office.MsoTriState.msoFalse,"free coordinate endpoints remain native unconnected handles");
            var beforeRotation=UniversalConnectors.Read(free);float cx=(beforeRotation.Begin.X+beforeRotation.End.X)/2,cy=(beforeRotation.Begin.Y+beforeRotation.End.Y)/2;free.Rotation+=90;float nativeRotation=free.Rotation;UniversalConnectors.Reflow(app);var rotated=UniversalConnectors.Read(free);Check(Math.Abs(rotated.Begin.X-(cx-(beforeRotation.Begin.Y-cy)))<.2&&Math.Abs(rotated.Begin.Y-(cy+(beforeRotation.Begin.X-cx)))<.2,"native quarter-turn updates endpoint metadata without rejecting rotated geometry");Check(Math.Abs(free.Rotation-nativeRotation)<.01,"metadata-only rotation capture preserves native rotation");
            free.Select();var changed=UniversalConnectors.Read(free);changed.Begin.X=120;changed.Begin.Y=280;changed.Route="elbow";changed.BeginArrow="stealth";UniversalConnectors.Update(app,changed);Check(UniversalConnectors.Read(free).Begin.X==120&&UniversalConnectors.Read(free).Route=="elbow"&&free.Line.BeginArrowheadStyle==Office.MsoArrowheadStyle.msoArrowheadStealth,"free endpoints route and start arrow can be edited");
            string priorXml=ConnectorCodec.Encode(UniversalConnectors.Read(free));int priorCount=slide.Shapes.Count;var bad=UniversalConnectors.Read(free);bad.End.X=1000;free.Select();bool refused=false;try{UniversalConnectors.Update(app,bad);}catch(InvalidDataException){refused=true;}Check(refused&&slide.Shapes.Count==priorCount&&ConnectorCodec.Encode(UniversalConnectors.Read(free))==priorXml,"off-slide update preflight preserves existing object and metadata");
            // Native chart points are measured by PowerPoint, not inferred from the data axis.
            var chart=slide.Shapes.AddChart2(-1,Office.XlChartType.xlColumnClustered,430,230,390,260,false);var all=(PowerPoint.SeriesCollection)chart.Chart.SeriesCollection();while(all.Count>1)all.Item(all.Count).Delete();if(all.Count==0)all.NewSeries();all.Item(1).Values=new double[]{10,20,30};all.Item(1).XValues=new string[]{"A","B","C"};chart.Chart.Refresh();var pointSpec=new ConnectorSpec {Route="straight",AutoRoute=false,Begin=new ConnectorEndpoint {Kind="point",ShapeId=chart.Id,Series=1,Point=2,Anchor="top"},End=new ConnectorEndpoint {Kind="free",X=900,Y=240}};var pointLine=UniversalConnectors.Create(app,pointSpec);int pointLineId=pointLine.Id;var before=UniversalConnectors.Read(pointLine).Begin;chart.Left+=20;chart.Chart.Refresh();UniversalConnectors.Reflow(app);var after=UniversalConnectors.Read(pointLine).Begin;
            Check(after.Kind=="point"&&Math.Abs((after.X-before.X)-20)<1&&Math.Abs(after.Y-before.Y)<1,"chart move refreshes tracked native point without losing binding");
            // Dragging the unmanaged connector geometry is interpreted as intentionally detaching a point.
            pointLine.Left+=15;UniversalConnectors.Reflow(app);Check(UniversalConnectors.Read(pointLine).Begin.Kind=="free","manual point endpoint geometry change becomes free rather than snapping back");
            pointLine.ConnectorFormat.BeginConnect(b,2);UniversalConnectors.Reflow(app);Check(UniversalConnectors.Read(pointLine).Begin.ShapeId==bid&&UniversalConnectors.Read(pointLine).Begin.Kind=="site","native reattachment of former chart point is adopted");
            // One corrupt connector must stop the whole preflight before any earlier binding is persisted.
            var freePart=free.CustomerData.Cast<Office.CustomXMLPart>().Single(p=>p.NamespaceURI==ConnectorCodec.Namespace);string validXml=freePart.XML;string lineBefore=ConnectorCodec.Encode(UniversalConnectors.Read(line));line.ConnectorFormat.BeginDisconnect();freePart=XmlPartUpdates.Shape(free,freePart,validXml.Replace("version=\"2\"","version=\"3\""));bool blocked=false;try{UniversalConnectors.Reflow(app);}catch(InvalidDataException){blocked=true;}
            Check(blocked&&line.ConnectorFormat.BeginConnected==Office.MsoTriState.msoFalse&&ConnectorCodec.Encode(UniversalConnectors.Read(line))==lineBefore,"all-connector preflight preserves earlier native edits and metadata when a later record is corrupt");freePart=XmlPartUpdates.Shape(free,freePart,validXml);line.ConnectorFormat.BeginConnect(ById(slide,cid),2);UniversalConnectors.Reflow(app);
            Check(c.TextFrame.TextRange.Text=="Unrelated target","connector workflows preserve target text");
            owned.SaveAs(file,PowerPoint.PpSaveAsFileType.ppSaveAsOpenXMLPresentation,Office.MsoTriState.msoFalse);owned.Close();owned=null;owned=app.Presentations.Open(file,Office.MsoTriState.msoFalse,Office.MsoTriState.msoFalse,Office.MsoTriState.msoTrue);slide=owned.Slides[1];line=ById(slide,lineId);free=ById(slide,freeId);pointLine=ById(slide,pointLineId);
            Check(UniversalConnectors.Read(line).Begin.ShapeId==cid&&UniversalConnectors.Read(line).End.ShapeId==aid&&line.ConnectorFormat.BeginConnectedShape.Id==cid,"live bindings and versioned metadata persist save/reopen");Check(UniversalConnectors.Read(free).Begin.Kind=="free"&&UniversalConnectors.Read(free).Route=="elbow"&&UniversalConnectors.Read(pointLine).Begin.ShapeId==bid,"free and migrated point/site states persist");
            line.ConnectorFormat.BeginDisconnect();UniversalConnectors.Reflow(app);Check(UniversalConnectors.Read(line).Begin.Kind=="free"&&line.ConnectorFormat.BeginConnected==Office.MsoTriState.msoFalse,"native detachment remains respected after reopen");owned.Save();Console.WriteLine("UNIVERSAL CONNECTOR "+count+" native assertions passed. Evidence deck: "+file);
        }
        finally{if(owned!=null){owned.Saved=Office.MsoTriState.msoTrue;owned.Close();}}
    }
}

